  ('ACNE_VULGARIS', 'QUESTION', 'Is the patient pregnant, planning pregnancy or breastfeeding?', '{}'::text[], NULL, '{}'::text[], 'Reynolds RV, Yeung H, Cheng CE, et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol. 2024;90(5):1006.e1-1006.e30. [citation to be verified by reviewer]', 6),
  ('ACNE_VULGARIS', 'TREATMENT', 'Topical retinoid (e.g. adapalene) as base therapy, with benzoyl peroxide', ARRAY['ADAPALENE','BENZOYL_PEROXIDE','ADAPALENE_BPO']::text[], 'FIRST', ARRAY['MILD','MODERATE']::text[], 'Reynolds RV, Yeung H, Cheng CE, et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol. 2024;90(5):1006.e1-1006.e30. [citation to be verified by reviewer]', 7),
