) AS v(code, kind, text, gens, line, sevs, ref, ord) JOIN cds_conditions cc ON cc.code = v.code;
WITH c AS (INSERT INTO cds_conditions (code, name, icd10_code, summary, refs, content_source) VALUES ('IMPETIGO', 'Impetigo', 'L01.0', 'Superficial bacterial infection (S. aureus / Strep. pyogenes) with honey-coloured crusts, common in children.', '[{"citation": "Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]", "key": "IDSA_SSTI_2014"}]'::jsonb, 'STARTER_DRAFT') RETURNING id)
