  ('IMPETIGO', 'OBSERVATION', 'Honey-coloured crusts around nose and mouth are typical.', '{}'::text[], NULL, '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 0),
  ('IMPETIGO', 'OBSERVATION', 'Bullous form is staphylococcal.', '{}'::text[], NULL, '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 1),
  ('IMPETIGO', 'QUESTION', 'Other children or contacts affected?', '{}'::text[], NULL, '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 2),
  ('IMPETIGO', 'QUESTION', 'Underlying eczema or scabies?', '{}'::text[], NULL, '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 3),
  ('IMPETIGO', 'QUESTION', 'Fever or spreading redness (deeper infection)?', '{}'::text[], NULL, '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 4),
  ('IMPETIGO', 'TREATMENT', 'Topical mupirocin or fusidic acid for limited lesions', ARRAY['MUPIROCIN','FUSIDIC_ACID']::text[], 'FIRST', ARRAY['MILD','MODERATE']::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 5),
  ('IMPETIGO', 'TREATMENT', 'Oral anti-staphylococcal antibiotic for extensive disease, per local antibiogram', '{}'::text[], 'FIRST', ARRAY['SEVERE']::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 6),
  ('IMPETIGO', 'TREATMENT', 'Hygiene; avoid sharing towels; school exclusion until crusts dry/after treatment per local policy', '{}'::text[], 'ADJUNCT', '{}'::text[], 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 7)
