-- Red flags
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('SJS_TEN', 'Possible Stevens-Johnson syndrome / toxic epidermal necrolysis', '{"all": ["SITE:MUCOSA"], "any": ["LESION:BULLA", "LESION:EROSION", "SYMPTOM:SKIN_PAIN", "LESION:VESICLE"]}'::jsonb, 'Mucosal involvement with blistering or painful skin: stop suspect drugs and arrange urgent hospital assessment.', 'Creamer D, Walsh SA, Dziewulski P, et al. U.K. guidelines for the management of Stevens-Johnson syndrome/toxic epidermal necrolysis in adults 2016. Br J Dermatol. 2016;174(6):1194-1227. [citation to be verified by reviewer]', 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('SKIN_PAIN_BLISTERS_DRUG', 'Painful skin with blisters after a new medicine', '{"all": ["SYMPTOM:SKIN_PAIN"], "any": ["LESION:BULLA", "LESION:EROSION"]}'::jsonb, 'Consider severe cutaneous adverse reaction; review recent drugs and assess urgently.', 'Creamer D, Walsh SA, Dziewulski P, et al. U.K. guidelines for the management of Stevens-Johnson syndrome/toxic epidermal necrolysis in adults 2016. Br J Dermatol. 2016;174(6):1194-1227. [citation to be verified by reviewer]', 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('FEVER_WIDESPREAD_RASH', 'Fever with widespread rash', '{"all": ["SYMPTOM:FEVER", "DIST:GENERALISED"]}'::jsonb, 'Consider drug reaction (e.g. DRESS), systemic infection or erythroderma; assess vital signs and refer urgently if unwell.', NULL, 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('ERYTHRODERMA', 'Erythroderma (extensive involvement)', '{"all": ["EXTENT_GE:80"]}'::jsonb, 'Erythroderma is a dermatological emergency (fluid, temperature, infection risks): urgent referral.', NULL, 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('CHANGING_PIGMENTED_LESION', 'Changing or bleeding pigmented lesion', '{"all": ["PROBLEM:GROWTH_LESION"], "any": ["SYMPTOM:LESION_CHANGE", "SYMPTOM:BLEEDING"]}'::jsonb, 'Assess with ABCDE criteria; refer for dermoscopy/biopsy under the suspected-cancer pathway.', 'National Institute for Health and Care Excellence. Melanoma: assessment and management (NG14). 2015, updated 2022. [citation to be verified by reviewer]', 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('OPHTHALMIC_ZOSTER', 'Zoster involving the eye region', '{"all": ["CONFIG:DERMATOMAL", "SITE:EYE_PERIOCULAR"]}'::jsonb, 'Same-day ophthalmology assessment; start antiviral therapy promptly.', 'Werner RN, Nikkels AF, Marinovic B, et al. European consensus-based (S2k) Guideline on the Management of Herpes Zoster. J Eur Acad Dermatol Venereol. 2017;31(1):9-29. [citation to be verified by reviewer]', 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('NONHEALING_ULCER', 'Non-healing ulcer over 6 weeks', '{"all": ["LESION:ULCER", "DURATION_GE_DAYS:42"]}'::jsonb, 'Consider malignancy, vascular disease or infection; biopsy/referral.', NULL, 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('CELLULITIS_SYSTEMIC', 'Spreading painful swelling with fever', '{"all": ["SYMPTOM:SWELLING", "SYMPTOM:PAIN", "SYMPTOM:FEVER"]}'::jsonb, 'Possible cellulitis or deeper infection; assess for sepsis and need for systemic antibiotics/admission.', 'Stevens DL, Bisno AL, Chambers HF, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the Infectious Diseases Society of America. Clin Infect Dis. 2014;59(2):e10-e52. [citation to be verified by reviewer]', 'STARTER_DRAFT');
INSERT INTO cds_red_flags (code, title, criteria, guidance, reference, content_source) VALUES ('ANGIOEDEMA_AIRWAY', 'Angioedema / possible anaphylaxis', '{"any": ["SYMPTOM:BREATHING_DIFFICULTY", "SYMPTOM:LIP_TONGUE_SWELLING"]}'::jsonb, 'Breathing difficulty or lip/tongue swelling: treat as possible anaphylaxis - emergency management.', 'Zuberbier T, Abdul Latiff AH, Abuzakouk M, et al. The international EAACI/GA2LEN/EuroGuiDerm/APAAACI guideline for the definition, classification, diagnosis, and management of urticaria. Allergy. 2022;77(3):734-766. [citation to be verified by reviewer]', 'STARTER_DRAFT');
